\begin{ex}%[7D6V2]
Tỉ số học sinh nữ và nam của một trường là ${\dfrac{4}{7}}$. Biết số học sinh nam nhiều hơn số học sinh nữ là $228$ em. Hỏi tổng số học sinh toàn trường là bao nhiêu? 
\choice
{ $835$ học sinh }
   { $837$ học sinh }
     { $823$ học sinh }
    { \True $836$ học sinh }
\loigiai{
Gọi số học sinh nữ, nam lần lượt là ${x, y}$ em.\\
Ta có $\dfrac{x}{y}= {\dfrac{4}{7}} $\\
Suy ra $\dfrac{x}{4}= \dfrac{y}{7}= \dfrac{y-x}{3}= \dfrac{x+y}{11} $\\
$ \dfrac{228}{3}= \dfrac{x+y}{11}$\\
Toàn trường có ${x+y=836 }$ học sinh
}\end{ex}

\begin{ex}%[7D6V2]
Tỉ số học sinh nữ và nam của một trường là ${\dfrac{1}{6}}$. Biết số học sinh nam nhiều hơn số học sinh nữ là $305$ em. Hỏi tổng số học sinh toàn trường là bao nhiêu? 
\choice
{ \True $427$ học sinh }
   { $429$ học sinh }
     { $407$ học sinh }
    { $425$ học sinh }
\loigiai{
Gọi số học sinh nữ, nam lần lượt là ${x, y}$ em.\\
Ta có $\dfrac{x}{y}= {\dfrac{1}{6}} $\\
Suy ra $\dfrac{x}{1}= \dfrac{y}{6}= \dfrac{y-x}{5}= \dfrac{x+y}{7} $\\
$ \dfrac{305}{5}= \dfrac{x+y}{7}$\\
Toàn trường có ${x+y=427 }$ học sinh
}\end{ex}

\begin{ex}%[7D6V2]
Trong đợt khuyên góp ủng hộ đồng bào lũ lụt, ba xã ${A, B, C}$ đã khuyên góp được số tiền theo tỉ lệ ${5:7:8}$. Hỏi mỗi xã ${A, B, C}$ khuyên góp lần lượt là bao nhiêu tiền biết xã ${B}$ khuyên góp nhiều hơn xã ${A}$ là $76$ triệu đồng. 
\choice
{  $170$; $266$; $324$ (triệu đồng)  }
   {  $190$; $291$; $279$ (triệu đồng) }
     { \True  $190$; $266$; $304$ (triệu đồng)  }
    {  $210$; $246$; $304$ (triệu đồng) }
\loigiai{
Gọi số tiền khuyên góp của ba xã ${A, B, C}$ lần lượt là ${x,y,z}$ triệu đồng.\\
Ta có $y-x=76$\\
Và $\dfrac{x}{5}= \dfrac{y}{7} =\dfrac{z}{8}=\dfrac{y-x}{7-5}=\dfrac{76}{2}=38 $\\
${x=190}$ và ${y=266}$; ${z=304}$
}\end{ex}

\begin{ex}%[7D6V2]
Tại một trang trại gia súc tỉ lệ nuôi trâu, bò, dê lần lượt là ${5:6:4}$. Biết tổng số trâu và dê là $198$ con. Hỏi số lượng trâu, bò, dê lần lượt là bao nhiêu. 
\choice
{  $90$ con trâu; $132$ con bò; $108$ con dê  }
   {  $130$ con trâu; $112$ con bò; $88$ con dê }
     {  $110$ con trâu; $157$ con bò; $63$ con dê }
    { \True  $110$ con trâu; $132$ con bò; $88$ con dê  }
\loigiai{
Gọi số trâu, bò, dê lần lượt là ${x,y,z}$ con.\\
Ta có $x+z=198$\\
Và $\dfrac{x}{5}= \dfrac{y}{6} =\dfrac{z}{4}=\dfrac{x+z}{5+4}=\dfrac{242}{9}=22 $\\
Trâu ${x=110}$ con và bò ${y=132}$ con; dê ${z=88}$ con
}\end{ex}

\begin{ex}%[7D6V2]
Tại một xí nghiệp trong một tháng ba đội sản xuất được tất cả $865$ sản phẩm. Biết số sản phẩm của ba đội sản xuất được theo tỉ lệ ${1:1:3}$. Hỏi mỗi đội sản xuất được bao nhiêu sản phẩm? 
\choice
{  $173$; $198$; $494$ (sản phẩm) }
   { \True  $173$; $173$; $519$ (sản phẩm)  }
     {  $193$; $153$; $519$ (sản phẩm) }
    {  $153$; $173$; $539$ (sản phẩm)  }
\loigiai{
Gọi số sản phẩm ba đội sản xuất được lần lượt là ${x,y,z}$ sản phẩm.\\
Ta có $x+y+z=865$\\
Và $\dfrac{x}{1}= \dfrac{y}{1} =\dfrac{z}{3}=\dfrac{x+y+z}{1+1+3}=\dfrac{865}{5}=173 $\\
${x=173}$ và ${y=173}$; ${z=519}$ (sản phẩm)
}\end{ex}

\begin{ex}%[7D6V2]
Thành phần mứt  dừa sau khi hoàn thành chỉ gồm có  dừa và đường theo tỉ lệ ${2:1}$. Trong $9$ kilôgam mứt  dừa có bao nhiêu kilôgam  dừa bao nhiêu kilôgam đường.
\choice
{ $9$ kilôgam  dừa; $3$ kilôgam đường  }
   { \True  $6$ kilôgam  dừa; $3$ kilôgam đường  }
     {  $6$ kilôgam  dừa; $9$ kilôgam đường  }
    {  $3$ kilôgam  dừa; $6$ kilôgam đường  }
\loigiai{
Gọi khối lượng  dừa và đường có trong $9$ kilôgam mứt lần lượt là ${x, y}$ kilogam\\
Ta có $\dfrac{x}{2}= \dfrac{y}{1}= \dfrac{x+y}{3} =\dfrac{9}{3}= 3$\\
dừa là $6$ kilôgam; đường là $3$ kilôgam.
}\end{ex}

\begin{ex}%[7D6V2]
Ba nhà đầu tư góp vốn để mở công ty theo tỷ lệ ${1:2:2}$. Cuối năm số tiền lợi nhuận công ty dự kiến trả là ba nhà đầu tư là $70$ triệu đồng chia theo tỷ lệ góp vốn. Tính số tiền lợi nhuận mỗi nhà đầu tư nhận được. 
\choice
{  $14$; $33$; $23$ (triệu đồng) }
   {  $9$; $28$; $33$ (triệu đồng)  }
     { \True  $14$; $28$; $28$ (triệu đồng)  }
    {  $19$; $23$; $28$ (triệu đồng) }
\loigiai{
Gọi số tiền góp vốn của ba nhà đầu tư lần lượt là ${x,y,z}$ triệu đồng.\\
Ta có $x+y+z=70$\\
Và $\dfrac{x}{1}= \dfrac{y}{2} =\dfrac{z}{2}=\dfrac{x+y+z}{1+2+2}=\dfrac{70}{5}=1 $\\
${x=14}$ và ${y=28}$; ${z=28}$
}\end{ex}

\begin{ex}%[7D6V2]
Biết $3$ lần tuổi của Lan bằng $4$ lần tuổi của Khôi. Mà Lan nhiều hơn Khôi là $3$ tuổi. Hỏi tuổi mỗi người?
\choice
{ \True  Khôi $9$ tuổi và Lan $12$ tuổi }
   { Khôi $10$ tuổi và Lan $13$ tuổi  }
     { Khôi $11$ tuổi và Lan $14$ tuổi  }
    {  Khôi $8$ tuổi và Lan $11$ tuổi }
\loigiai{
Gọi số tuổi của Lan và Khôi lần lượt là ${x, y}$\\
Ta có $3x=4y$\\
Suy ra $ \dfrac{x}{4}=  \dfrac{y}{3} =  \dfrac{x-y}{1} =3$\\
Vây Khôi $9$ tuổi và Lan $12$ tuổi.
}\end{ex}

\begin{ex}%[7D6V2]
